(()=>{'use strict';
const C=SingerCore,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let dataset=null,fileName='',importedAt='',editing=null,current=null,importVersion=0,autoCity='';
const form=$('singer-form'),field=name=>form.elements.namedItem(name),message=text=>{$('singer-message').textContent=text};
function all(){const x=C.read(localStorage,C.analysesKey,[]);return Array.isArray(x)?x:[]}
function refs(){const x=C.read(localStorage,C.referencesKey,{});return !Array.isArray(x)?x:{}}
function persist(analyses,references){const oldA=localStorage.getItem(C.analysesKey),oldR=localStorage.getItem(C.referencesKey);try{localStorage.setItem(C.analysesKey,JSON.stringify(analyses));localStorage.setItem(C.referencesKey,JSON.stringify(references));return true}catch{try{if(oldA===null)localStorage.removeItem(C.analysesKey);else localStorage.setItem(C.analysesKey,oldA);if(oldR===null)localStorage.removeItem(C.referencesKey);else localStorage.setItem(C.referencesKey,oldR)}catch{}message('Speicherung fehlgeschlagen. Die Eingaben bleiben geöffnet; bitte Browserspeicher prüfen.');return false}}
function changed(){current=null;$('singer-output').textContent='';$('singer-save').disabled=true;$('singer-copy').disabled=true}
function filter(){return {zipcode:field('zipcode').value.trim(),rooms:field('rooms').value,kind:field('kind').value,activeOnly:field('activeOnly').checked}}
function averages(){changed();const f=filter(),selected=dataset?C.select(dataset.rows,f):[],avg=C.average(selected),manual=field('averageMode').value==='manual';field('averagePrice').readOnly=!manual;field('averageDom').readOnly=!manual;if(!manual){field('averagePrice').value=avg?String(avg.price):'';field('averageDom').value=avg?String(avg.dom):''}const cities=[...new Set(selected.map(r=>r.city).filter(Boolean))];if(cities.length===1&&(!field('city').value||field('city').value===autoCity)){field('city').value=cities[0];autoCity=cities[0]}$('singer-import-info').textContent=dataset?`${fileName}: ${dataset.total} Zeilen · ${dataset.rows.length} verwertbar · ${dataset.invalid} ungültig · ${dataset.duplicates} doppelt · ${selected.length} passend zur Auswahl.`:'Noch keine CSV geladen. Alternativ Immometrica-Durchschnittswerte manuell eingeben.'}
function fillOptions(){const zips=[...new Set(dataset?.rows.map(r=>r.zipcode)||[])],rooms=[...new Set(dataset?.rows.map(r=>r.rooms)||[])];$('singer-zips').innerHTML=zips.map(z=>`<option value="${esc(z)}">`).join('');if(zips.length===1)field('zipcode').value=zips[0];if(rooms.length===1)field('rooms').value=rooms[0];if(dataset?.rows.every(r=>r.kind==='haus'))field('kind').value='haus';const cities=[...new Set(dataset?.rows.map(r=>r.city).filter(Boolean)||[])];if(cities.length===1&&!field('city').value){field('city').value=cities[0];autoCity=cities[0]}field('activeOnly').disabled=!!dataset&&!dataset.hasActive;if(dataset&&!dataset.hasActive)field('activeOnly').checked=false}
function build(){if(!field('confirmed').checked)throw Error('Bitte bestätigen, dass die verwendeten Daten ausschließlich aus Immometrica stammen.');const f=filter(),rooms=Number(f.rooms);if(!/^\d{5}$/.test(f.zipcode)||!Number.isFinite(rooms)||rooms<=0||!['wohnung','haus'].includes(f.kind)||!field('city').value.trim())throw Error('Bitte PLZ, Zimmeranzahl, Objektart und Stadt/Region ausfüllen.');const selected=dataset?C.select(dataset.rows,f):[],avg=field('averageMode').value==='csv'?C.average(selected):{price:Number(field('averagePrice').value),dom:field('averageDom').value===''?NaN:Number(field('averageDom').value)};if(!avg)throw Error('Für diese Auswahl gibt es keine auswertbaren CSV-Angebote. Bitte Auswahl oder Aktiv-Filter prüfen.');const result=C.corridor(avg.price,avg.dom),objectLabel=field('objectLabel').value.trim()||new Intl.NumberFormat('de-DE').format(rooms)+'-Zimmer-'+(f.kind==='wohnung'?'Wohnungen':'Häuser');return {id:editing||crypto.randomUUID(),city:field('city').value.trim(),zipcode:f.zipcode,rooms,kind:f.kind,objectLabel,activeOnly:f.activeOnly,averageMode:field('averageMode').value,averagePrice:avg.price,averageDom:avg.dom,result,output:C.format(result,field('city').value,objectLabel),count:selected.length,dataset,fileName,importedAt,confirmed:true,rules:{...C.rules},ruleVersion:'singer-60-90-v1-uplift30',updatedAt:new Date().toISOString()}}
function output(){try{if(!form.reportValidity())return;current=build();$('singer-output').textContent=current.output;$('singer-save').disabled=false;$('singer-copy').disabled=false;message('')}catch(e){changed();message(e.message)}}
function notify(){ImmoMarket.refresh();currentPage=1;render();renderObjects();if(typeof window.renderOwned==='function')window.renderOwned()}
function renderSaved(){const references=refs();$('singer-saved').innerHTML=all().sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).map(a=>{const ref=references[C.key(a.zipcode,a.rooms,a.kind)],active=ref?.analysisId===a.id;return `<article class="singer-saved"><div class="singer-heading"><h3>${esc(a.zipcode)} · ${esc(a.city)} · ${esc(a.objectLabel)}</h3><small>${esc(new Date(a.updatedAt).toLocaleString('de-DE'))}${active?' · Als Inserat-Marktwert aktiv':''}</small></div><pre class="singer-output">${esc(a.output)}</pre><div class="singer-actions"><button type="button" data-singer-edit="${esc(a.id)}">Bearbeiten</button><button type="button" data-singer-copy="${esc(a.id)}">Ergebnis kopieren</button><button type="button" data-singer-delete="${esc(a.id)}">Löschen</button></div><div class="singer-actions"><label>Vergleichswert für passende Inserate<select data-singer-basis="${esc(a.id)}"><option value="lower" ${!active||ref.basis==='lower'?'selected':''}>Untergrenze · 60 Tage</option><option value="middle" ${active&&ref.basis==='middle'?'selected':''}>Mitte des Korridors</option><option value="upper" ${active&&ref.basis==='upper'?'selected':''}>Obergrenze · 90 Tage</option></select></label><button type="button" data-singer-use="${esc(a.id)}">Als Marktwert für diese PLZ / Zimmer übernehmen</button>${active?`<button type="button" data-singer-unuse="${esc(a.id)}">Vergleichswert deaktivieren</button>`:''}</div></article>`}).join('')||'<p class="saved-note">Noch keine Immometrica-Auswertung gespeichert.</p>'}
function reset(){importVersion++;editing=null;dataset=null;fileName='';autoCity='';importedAt='';form.reset();field('averageMode').value='csv';field('kind').value='wohnung';field('activeOnly').checked=true;field('activeOnly').disabled=false;$('singer-file').value='';$('singer-zips').innerHTML='';averages();message('')}
$('singer-file').onchange=async()=>{const file=$('singer-file').files?.[0];if(!file)return;const version=++importVersion;changed();dataset=null;fileName='';importedAt='';message('CSV wird lokal eingelesen …');try{if(file.size>5*1024*1024)throw Error('Maximal 5 MB pro CSV.');const bytes=await file.arrayBuffer();let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(bytes)}catch{text=new TextDecoder('windows-1252').decode(bytes)}const parsed=C.parse(text);if(version!==importVersion)return;dataset=parsed;autoCity=field('city').value;fileName=file.name.slice(0,250);importedAt=new Date().toISOString();field('averageMode').value='csv';field('activeOnly').checked=parsed.hasActive;fillOptions();averages();message('CSV eingelesen. Auswahl und Datenherkunft prüfen, dann auswerten.')}catch(e){if(version===importVersion){dataset=null;averages();message(e.message)}}};
form.onsubmit=e=>{e.preventDefault();output()};for(const name of ['zipcode','rooms','kind','activeOnly','averageMode'])field(name).addEventListener('change',averages);for(const name of ['city','objectLabel','averagePrice','averageDom','confirmed'])field(name).addEventListener('input',changed);$('singer-new').onclick=reset;
$('singer-save').onclick=()=>{if(!current)return;const next=all(),i=next.findIndex(a=>a.id===current.id);if(i>=0)next[i]=current;else next.push(current);const references={...refs()};for(const [key,ref]of Object.entries(references))if(ref.analysisId===current.id){delete references[key];references[C.key(current.zipcode,current.rooms,current.kind)]=C.referenceFrom(current,ref.basis)}if(!persist(next,references))return;editing=current.id;renderSaved();notify();message('Auswertung und verwendete CSV-Angebotsdaten auf diesem Gerät gespeichert.')};
async function copy(value){try{await navigator.clipboard.writeText(value);message('Ergebnis kopiert.')}catch{message('Kopieren nicht verfügbar. Bitte den Ergebnistext direkt markieren und kopieren.')}}$('singer-copy').onclick=()=>{if(current)copy(current.output)};
$('singer-saved').onclick=e=>{const button=e.target.closest('button');if(!button)return;const id=button.dataset.singerEdit||button.dataset.singerCopy||button.dataset.singerDelete||button.dataset.singerUse||button.dataset.singerUnuse,a=all().find(x=>x.id===id);if(!a)return;const references={...refs()};if(button.dataset.singerEdit){if(current&&!confirm('Aktuelle Eingaben verlassen und diese Auswertung bearbeiten?'))return;importVersion++;editing=a.id;dataset=a.dataset;fileName=a.fileName;importedAt=a.importedAt;form.reset();for(const name of ['zipcode','rooms','kind','city','objectLabel','averageMode','averagePrice','averageDom'])field(name).value=a[name]??'';field('confirmed').checked=true;field('activeOnly').checked=a.activeOnly;field('activeOnly').disabled=!!dataset&&!dataset.hasActive;fillOptions();for(const name of ['zipcode','rooms','kind','city'])field(name).value=a[name]??'';averages();current=a;$('singer-output').textContent=a.output;$('singer-save').disabled=false;$('singer-copy').disabled=false;field('zipcode').focus();message('Gespeicherte Auswertung geöffnet. Nach Änderungen erneut auswerten und speichern.');return}if(button.dataset.singerCopy){copy(a.output);return}if(button.dataset.singerDelete){if(!confirm('Diese Auswertung und ihre gespeicherten CSV-Angebotsdaten löschen? Ein zugehöriger Inserat-Vergleichswert wird ebenfalls entfernt.'))return;for(const [key,r]of Object.entries(references))if(r.analysisId===id)delete references[key];if(!persist(all().filter(x=>x.id!==id),references))return;if(editing===id)reset()}else if(button.dataset.singerUse){const basis=$('singer-saved').querySelector(`[data-singer-basis="${id}"]`).value;references[C.key(a.zipcode,a.rooms,a.kind)]=C.referenceFrom(a,basis);if(!persist(all(),references))return;message('Vergleichswert für '+a.zipcode+' / '+a.rooms+' Zimmer übernommen. Individuelle Objektwerte haben Vorrang.')}else if(button.dataset.singerUnuse){for(const [key,r]of Object.entries(references))if(r.analysisId===id)delete references[key];if(!persist(all(),references))return;message('Immometrica-Vergleichswert deaktiviert. Andere Marktwerte bleiben erhalten.')}renderSaved();notify()};
window.addEventListener('storage',e=>{if([C.analysesKey,C.referencesKey,null].includes(e.key)){renderSaved();notify()}});averages();renderSaved();
})();
